static void hp_work_timer_expiry(wdparm_t arg)
{
  irqstate_t flags = enter_critical_section();
  dq_addlast((FAR dq_entry_t *)arg, &g_hpwork.q);
  nxsem_post(&g_hpwork.sem);
  leave_critical_section(flags);
}
#endif

